#include <vector>
#include <cmath>

class Solution {
public:
    long long elevatorTotalTravel(std::vector<int>& requests, int startFloor) {
        long long total = 0;
        int cur = startFloor;
        for (int req : requests) {
            total += std::abs(req - cur);
            cur = req;
        }
        return total;
    }
};

class Solution {
    public long elevatorTotalTravel(int[] requests, int startFloor) {
        long total = 0;
        int cur = startFloor;
        for (int req : requests) {
            total += Math.abs(req - cur);
            cur = req;
        }
        return total;
    }
}

function elevatorTotalTravel(requests, startFloor) {
    let cur = startFloor;
